import{_ as o,a0 as s,w as u,s as p,ao as r,I as a,a1 as n,A as e,x as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"为什么黑客更喜欢使用 Kali Linux？ | LCTT x X-CMD","titleTemplate":false,"description":"为什么黑客更喜欢使用 Kali Linux？ | LCTT (202307) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"为什么黑客更喜欢使用 Kali Linux？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"为什么黑客更喜欢使用 Kali Linux？ | LCTT (202307) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202307/20230628.1 ⭐️⭐️ Why is Kali Linux Preferred by Hackers","title":"为什么黑客更喜欢使用 Kali Linux？","tag":"202307","desc":""},"relativePath":"202307/20230628.1 ⭐️⭐️ Why is Kali Linux Preferred by Hackers.md","filePath":"[post].md"}'),d={name:"202307/20230628.1 ⭐️⭐️ Why is Kali Linux Preferred by Hackers.md"};function x(h,l,L,g,m,b){const t=s("Link");return u(),p("div",null,[l[19]||(l[19]=r('<h1 id="为什么黑客更喜欢使用-kali-linux" tabindex="-1">为什么黑客更喜欢使用 Kali Linux？ <a class="header-anchor" href="#为什么黑客更喜欢使用-kali-linux" aria-label="Permalink to “为什么黑客更喜欢使用 Kali Linux？”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202307/04/151945ol68v2ez28e6exzq.jpg" alt=""></p><blockquote><p>以下是为什么大多数黑客和渗透测试人员喜欢使用 Kali Linux 的几个原因。</p></blockquote><p>Kali Linux 是一个基于 Debian “测试版” 的 Linux 操作系统，创建于近十年前。在过去几年里，它在黑客和网络安全专业人员中非常流行。随着对数字基础设施的越来越多的依赖和网络威胁的不断增长，网络安全对于普通用户和企业来说变得更加重要。</p><p>道德黑客和渗透测试人员在识别漏洞和加强系统安全方面发挥着重要作用。由于 Kali Linux 具备为安全测试和分析而量身定制的全面工具和功能，因此成为他们的首选操作系统。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/05/Kali-Linux-with-Xfce-Desktop-Environment.jpg" alt="带有 Xfce 桌面环境的 Kali Linux"></p><h3 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to “概述”">​</a></h3>',7)),a("p",null,[n(t,{href:"https://www.kali.org/"},{default:e(()=>[...l[0]||(l[0]=[i("Kali Linux",-1)])]),_:1}),l[1]||(l[1]=i(" 由 Offensive Security（一家美国信息安全公司）维护，并得到社区中数千名贡献者的支持。它跟随 Debian 的 “测试版” 分支的发展，保持与最新软件包的同步，为黑客们提供了最新模块来进行工作。",-1))]),l[20]||(l[20]=r('<p>此外，Kali Linux 支持多种架构，例如 x86、x86-64、armel 和 armhf，这有助于黑客在广泛的硬件范围内使用。</p><p>使用此发行版的最大优势之一是它适用于多个技术平台，你可以下载和使用。以下是其中一些平台：</p><ul><li>32 位和 64 位的安装镜像（ISO）</li><li>预构建的虚拟机镜像</li><li>ARM 架构镜像</li><li>用于移动设备的安卓镜像</li><li>Docker 和 LXD 镜像</li><li>可在各个厂商提供的云中使用</li><li>只读的 LIVE ISO 镜像</li><li>可在 Windows 的 Linux 子系统（WSL）上使用</li></ul><h3 id="为何它备受青睐" tabindex="-1">为何它备受青睐 <a class="header-anchor" href="#为何它备受青睐" aria-label="Permalink to “为何它备受青睐”">​</a></h3><h4 id="强大的渗透测试工具" tabindex="-1">强大的渗透测试工具 <a class="header-anchor" href="#强大的渗透测试工具" aria-label="Permalink to “强大的渗透测试工具”">​</a></h4><p>Kali Linux 提供了丰富的渗透测试工具，使黑客能够识别并利用漏洞。这些工具包括网络扫描器、密码破解器、无线攻击框架和 Web 应用程序评估工具。这个操作系统内置了如此之多的工具，极大地简化了黑客的工作流程，使他们能够有效专注于目标。</p><h4 id="全面的安全评估" tabindex="-1">全面的安全评估 <a class="header-anchor" href="#全面的安全评估" aria-label="Permalink to “全面的安全评估”">​</a></h4><p>使用这个发行版，黑客可以对各种目标进行全面的安全评估。他们可以模拟真实攻击，分析系统弱点，制定有效的安全策略。该操作系统提供了漏洞扫描、网络映射和系统指纹识别等工具，使黑客能够从不同角度评估目标系统的安全状况。</p><h4 id="反取证分析和事件响应" tabindex="-1">反取证分析和事件响应 <a class="header-anchor" href="#反取证分析和事件响应" aria-label="Permalink to “反取证分析和事件响应”">​</a></h4><p>Kali Linux 还包括用于数字取证和事件响应的工具。黑客可以利用这些工具来调查安全漏洞，收集证据和分析受损系统。该操作系统支持数据恢复、内存分析和网络取证，有助于进行彻底的调查，并帮助恢复遭受损害的系统。</p><h4 id="无线网络审计" tabindex="-1">无线网络审计 <a class="header-anchor" href="#无线网络审计" aria-label="Permalink to “无线网络审计”">​</a></h4><p>由于其固有的弱点，无线网络往往是黑客的主要目标。Kali Linux 提供了全面的用于审计和保护无线网络的工具。黑客可以使用这些工具来识别弱加密协议，发现隐藏网络，并进行数据包分析以检测恶意活动。这使得他们能够评估无线网络的安全性并提出缓解策略。</p><h3 id="大量的工具" tabindex="-1">大量的工具 <a class="header-anchor" href="#大量的工具" aria-label="Permalink to “大量的工具”">​</a></h3><p>以下是默认情况下（截至最新版本）Kali Linux 提供的一些工具类别的简要列表：</p><ul><li><strong>信息收集</strong><ul><li>DNS 分析</li><li>IDS/IPS 识别</li><li>活动主机识别</li><li>网络和端口扫描器</li><li>OSINT 分析</li><li>路由分析</li><li>SMB 分析</li><li>SMTP 分析</li><li>SNMP 分析</li><li>SSL 分析</li></ul></li><li><strong>漏洞分析</strong><ul><li>模糊测试工具</li><li>VoIP 工具</li></ul></li><li><strong>Web 应用程序分析</strong><ul><li>CMS 和框架识别</li><li>Web 应用程序代理</li><li>Web 爬虫和目录暴力破解</li><li>Web 漏洞扫描器</li></ul></li><li><strong>数据库评估</strong><ul><li>SQLite 数据库浏览器</li></ul></li><li><strong>密码攻击</strong><ul><li>离线攻击工具</li><li>在线攻击工具</li><li>哈希传递工具</li><li>密码分析和密码列表</li></ul></li><li><strong>无线网络攻击</strong><ul><li>802.11 无线工具</li><li>蓝牙攻击工具</li></ul></li><li><strong>逆向工程工具</strong><ul><li>Clang</li><li>NASM shell</li></ul></li><li><strong>利用工具</strong><ul><li>Metasploit</li><li>Searchsploit</li><li>MSF 载荷生成器</li><li>社会工程学工具包</li></ul></li><li><strong>嗅探和欺骗</strong><ul><li>网络嗅探器</li><li>欺骗和中间人攻击</li><li>后渗透</li></ul></li><li><strong>取证</strong><ul><li>反取证工具</li><li>取证镜像工具</li><li>PDF 取证工具</li><li>Sleuth Kit 套件</li></ul></li><li><strong>报告工具</strong><ul><li>Cutycapt</li><li>Faraday start</li><li>Pipal</li></ul></li><li><strong>社会工程学工具</strong></li></ul><p>你可以在详尽的工具门户网站了解更多信息：</p>',16)),a("blockquote",null,[a("p",null,[a("strong",null,[n(t,{href:"https://www.kali.org/tools/"},{default:e(()=>[...l[2]||(l[2]=[i("访问 Kali Linux 工具门户网站",-1)])]),_:1})])])]),l[21]||(l[21]=r('<p><img src="https://www.debugpoint.com/wp-content/uploads/2023/05/Kali-Linux-Tools.jpg" alt="Kali Linux Tools"></p><h3 id="开源特性" tabindex="-1">开源特性 <a class="header-anchor" href="#开源特性" aria-label="Permalink to “开源特性”">​</a></h3><p>黑客偏爱 Kali Linux 的主要原因之一是它的开源特性。作为一款开源操作系统，Kali Linux 允许黑客访问和修改源代码以满足其需求。这使得他们可以自由定制系统并添加自己的工具或功能。开源社区还积极参与开发和改进 Kali Linux，以确保其与最新的安全技术保持同步。</p><h3 id="社区支持与合作" tabindex="-1">社区支持与合作 <a class="header-anchor" href="#社区支持与合作" aria-label="Permalink to “社区支持与合作”">​</a></h3><p>Kali Linux 拥有一个庞大的安全专业人员、黑客和爱好者社区。这个社区通过分享知识、开发新工具和为其他用户提供支持来积极合作，以增强操作系统的功能。</p><p>可通过论坛、在线教程和社区驱动的文档获取宝贵资源并在需要时寻求帮助，确保使用 Kali Linux 的黑客能够获得支持。</p><p>团队还提供了多种培训和学习方式。其中也包括了一个学习路径，供希望在网络安全领域追求职业发展的学生参考，并提供相关认证。</p><h3 id="定制和灵活性" tabindex="-1">定制和灵活性 <a class="header-anchor" href="#定制和灵活性" aria-label="Permalink to “定制和灵活性”">​</a></h3><p>另一个优点是 Kali Linux 高度的定制和灵活性。黑客可以根据自己的特定需求和喜好来定制操作系统。他们可以按照自己的要求安装和配置工具，创建自定义脚本并构建个性化的工作流程。这种定制水平使得黑客可以优化自己的生产力并简化渗透测试过程。</p><h3 id="持续更新和改进" tabindex="-1">持续更新和改进 <a class="header-anchor" href="#持续更新和改进" aria-label="Permalink to “持续更新和改进”">​</a></h3><p>Kali Linux 是一个不断更新和改进的操作系统。开发人员和社区成员积极致力于增强现有工具、添加新功能并解决任何安全漏洞。这些更新确保使用 Kali Linux 的黑客可以获得最新的工具和技术，使他们始终处于网络安全进展的前沿。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/06/Kali-Linux-distribute-packages-from-its-own-sources.jpg" alt="Kali Linux 从其自己的源分发软件包"></p><h3 id="道德使用" tabindex="-1">道德使用 <a class="header-anchor" href="#道德使用" aria-label="Permalink to “道德使用”">​</a></h3><p>重要的是要注意，Kali Linux 旨在用于道德黑客和安全测试目的。道德黑客利用他们的技能来发现漏洞并保护系统，而不是从事恶意活动。</p><p>Kali Linux 倡导对黑客工具的负责和合法使用，强调获得适当授权和遵守道德准则的重要性。该操作系统是网络安全专业人员增强组织安全性、促进更安全的数字环境的强大工具。</p><p>简而言之，<strong>请勿将</strong> Kali Linux 用于非法或未经授权的用途。</p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>我希望这份概述介绍了 Kali Linux 及其为全球安全专业人员所偏爱的免费开源操作系统的原因。它以 Debian 为基础，配备了数千种工具和便捷的访问方式，使它成为每个人都值得考虑的选择。</p>',18)),a("p",null,[l[4]||(l[4]=i("你可以在 ",-1)),n(t,{href:"https://www.kali.org/get-kali/"},{default:e(()=>[...l[3]||(l[3]=[i("官方网站",-1)])]),_:1}),l[5]||(l[5]=i(" 上下载 Kali Linux。",-1))]),l[22]||(l[22]=a("p",null,[a("em",null,"（题图：MJ/95d89a95-50fe-4fdf-a06a-e4287092cee9）")],-1)),l[23]||(l[23]=a("hr",null,null,-1)),a("p",null,[l[7]||(l[7]=i("via: ",-1)),n(t,{href:"https://www.debugpoint.com/why-kali-linux/"},{default:e(()=>[...l[6]||(l[6]=[i("https://www.debugpoint.com/why-kali-linux/",-1)])]),_:1})]),a("p",null,[l[11]||(l[11]=i("作者：",-1)),n(t,{href:"https://www.debugpoint.com/author/admin1/"},{default:e(()=>[...l[8]||(l[8]=[i("Arindam",-1)])]),_:1}),l[12]||(l[12]=i(" 选题：",-1)),n(t,{href:"https://github.com/lkxed/"},{default:e(()=>[...l[9]||(l[9]=[i("lkxed",-1)])]),_:1}),l[13]||(l[13]=i(" 译者：ChatGPT 校对：",-1)),n(t,{href:"https://github.com/wxy"},{default:e(()=>[...l[10]||(l[10]=[i("wxy",-1)])]),_:1})]),a("p",null,[l[16]||(l[16]=i("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...l[14]||(l[14]=[i("LCTT",-1)])]),_:1}),l[17]||(l[17]=i(" 原创编译，",-1)),n(t,{href:"https://linux.cn/"},{default:e(()=>[...l[15]||(l[15]=[i("Linux中国",-1)])]),_:1}),l[18]||(l[18]=i(" 荣誉推出",-1))])])}const w=o(d,[["render",x]]);export{T as __pageData,w as default};
